class TestStateTransitions:
    """Validate legal state transitions and reject illegal ones."""

    def test_idle_to_connecting(self, mesh_node, peer_node):
        """Connect must transition IDLE -> CONNECTING."""
        mesh_node.connect(peer_node)
        assert mesh_node.state in ("CONNECTING", "CONNECTED")

    def test_connecting_to_connected(self, mesh_node, peer_node):
        """After successful handshake, state must be CONNECTED."""
        mesh_node.connect(peer_node)
        assert mesh_node.state == "CONNECTED"

    def test_connected_to_disconnected(self, connected_pair):
        """Disconnect must transition CONNECTED -> DISCONNECTED."""
        mesh_node, peer_node = connected_pair
        mesh_node.disconnect(peer_node)
        assert mesh_node.state == "DISCONNECTED"

    def test_disconnected_to_idle(self, connected_pair):
        """After disconnect, node must return to IDLE when no peers remain."""
        mesh_node, peer_node = connected_pair
        mesh_node.disconnect(peer_node)
        assert mesh_node.state == "IDLE"

    def test_illegal_transition_from_idle_disconnect(self, mesh_node):
        """Disconnect from IDLE must raise PeerConnectionError."""
        with pytest.raises(PeerConnectionError):
            mesh_node.disconnect(None)

    def test_illegal_transition_double_connect(self, mesh_node, peer_node):
        """Double connect to same peer must be idempotent or raise."""
        mesh_node.connect(peer_node)
        # Second connect should either succeed idempotently or raise
        try:
            mesh_node.connect(peer_node)
            assert mesh_node.state == "CONNECTED"
        except PeerConnectionError:
            pass  # Acceptable if implementation rejects duplicate connections

    def test_peer_registry_after_connect(self, connected_pair):
        """Connected peer must appear in peer registry."""
        mesh_node, peer_node = connected_pair
        assert peer_node.node_id in mesh_node.peers

    def test_peer_registry_after_disconnect(self, connected_pair):
        """Disconnected peer must be removed from registry."""
        mesh_node, peer_node = connected_pair
        mesh_node.disconnect(peer_node)
        assert peer_node.node_id not in mesh_node.peers


