class TestMessagePath:
    """Validate end-to-end message delivery between connected peers."""

    def test_send_receive_roundtrip(self, connected_pair):
        """Message sent by one node must be received by the other."""
        mesh_node, peer_node = connected_pair
        payload = {"type": "ping", "data": "hello"}
        mesh_node.send(peer_node.node_id, payload)
        received = peer_node.receive()
        assert received is not None
        assert received["type"] == "ping"
        assert received["data"] == "hello"

    def test_message_ordering(self, connected_pair):
        """Messages must be received in FIFO order."""
        mesh_node, peer_node = connected_pair
        for i in range(10):
            mesh_node.send(peer_node.node_id, {"seq": i})
        for i in range(10):
            msg = peer_node.receive()
            assert msg["seq"] == i

    def test_message_payload_integrity(self, connected_pair):
        """Complex payloads must survive the round-trip unchanged."""
        mesh_node, peer_node = connected_pair
        complex_payload = {
            "nested": {"list": [1, 2, 3], "dict": {"a": 1}},
            "bytes": b"\x00\x01\x02",
            "unicode": "héllo wörld ✓",
            "float": 3.14159,
            "bool": True,
            "null": None,
        }
        mesh_node.send(peer_node.node_id, complex_payload)
        received = peer_node.receive()
        assert received == complex_payload

    def test_send_to_unknown_peer(self, mesh_node):
        """Sending to non-existent peer must raise PeerNotFoundError."""
        with pytest.raises(PeerNotFoundError):
            mesh_node.send("nonexistent-peer", {"data": "test"})

    def test_receive_without_messages(self, mesh_node):
        """Receive with empty queue must return None or raise."""
        result = mesh_node.receive()
        assert result is None

    def test_broadcast_to_all_peers(self, mesh_node, peer_node):
        """Broadcast must deliver to all connected peers."""
        third_node = MeshNode(node_id="tier0-node-003")
        mesh_node.connect(peer_node)
        mesh_node.connect(third_node)
        mesh_node.broadcast({"type": "broadcast"})
        assert peer_node.receive()["type"] == "broadcast"
        assert third_node.receive()["type"] == "broadcast"

    def test_message_ttl_expiry(self, connected_pair):
        """Messages with expired TTL must be dropped."""
        mesh_node, peer_node = connected_pair
        mesh_node.send(peer_node.node_id, {"data": "expired"}, ttl=-1)
        result = peer_node.receive()
        assert result is None


