class TestPropertyBased:
    """Fuzz testing for invariants that must always hold."""

    @settings(max_examples=50, suppress_health_check=[HealthCheck.too_slow])
    @given(
        payload=st.dictionaries(
            keys=st.text(min_size=1, max_size=20),
            values=st.one_of(
                st.integers(),
                st.text(),
                st.booleans(),
                st.floats(allow_nan=False, allow_infinity=False),
                st.lists(st.integers(), max_size=10),
            ),
            max_size=5,
        )
    )
    def test_payload_roundtrip_invariant(self, connected_pair, payload):
        """Any serializable payload must survive round-trip unchanged."""
        mesh_node, peer_node = connected_pair
        mesh_node.send(peer_node.node_id, payload)
        received = peer_node.receive()
        assert received == payload

    @settings(max_examples=20)
    @given(
        node_id=st.text(min_size=1, max_size=64, alphabet=string.ascii_letters + string.digits + "-_")
    )
    def test_node_id_preservation(self, node_id):
        """Any valid node_id must be preserved exactly."""
        node = MeshNode(node_id=node_id)
        assert node.node_id == node_id

    @settings(max_examples=20)
    @given(
        message_count=st.integers(min_value=1, max_value=50)
    )
    def test_fifo_ordering_invariant(self, connected_pair, message_count):
        """FIFO ordering must hold for arbitrary message counts."""
        mesh_node, peer_node = connected_pair
        for i in range(message_count):
            mesh_node.send(peer_node.node_id, {"seq": i})
        received_seqs = [peer_node.receive()["seq"] for _ in range(message_count)]
        assert received_seqs == list(range(message_count))


