# Tier 0: Concurrency & Thread Safety
# ---------------------------------------------------------------------------
class TestConcurrency:
    """Validate thread-safety of concurrent operations."""

    def test_concurrent_sends(self, connected_pair):
        """Concurrent sends from multiple threads must not corrupt state."""
        mesh_node, peer_node = connected_pair
        num_threads = 10
        messages_per_thread = 20

        def send_messages(thread_id):
            for i in range(messages_per_thread):
                mesh_node.send(peer_node.node_id, {"thread": thread_id, "seq": i})

        threads = [
            threading.Thread(target=send_messages, args=(t,))
            for t in range(num_threads)
        ]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        total_messages = num_threads * messages_per_thread
        received = [peer_node.receive() for _ in range(total_messages)]
        assert len(received) == total_messages
        # Verify all messages present
        counter = Counter((msg["thread"], msg["seq"]) for msg in received)
        assert len(counter) == total_messages

    def test_concurrent_connect_disconnect(self, mesh_node, peer_node):
        """Concurrent connect/disconnect must not deadlock or corrupt."""
        stop_flag = threading.Event()

        def connect_loop():
            while not stop_flag.is_set():
                try:
                    mesh_node.connect(peer_node)
                    mesh_node.disconnect(peer_node)
                except (PeerConnectionError, PeerNotFoundError):
                    pass

        threads = [threading.Thread(target=connect_loop) for _ in range(5)]
        for t in threads:
            t.start()
        time.sleep(0.1)  # Let them run briefly
        stop_flag.set()
        for t in threads:
            t.join()
        # State must be consistent after chaos
        assert mesh_node.state in ("IDLE", "CONNECTED", "DISCONNECTED")


